const el=s=>document.querySelector(s);const ns='http://www.w3.org/2000/svg';const fmt=n=>String(n).replace('-', '−').replace('.', ',');const save={get(k){try{return localStorage.getItem('fondasi-bilangan-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-bilangan-'+k,v);return true}catch{return false}}};
function ticks(id){for(let n=-6;n<=6;n++){const x=300+n*45,g=document.createElementNS(ns,'g');const line=document.createElementNS(ns,'line');for(const [k,v] of Object.entries({x1:x,x2:x,y1:93,y2:107,stroke:'#244d40'}))line.setAttribute(k,v);const t=document.createElementNS(ns,'text');t.setAttribute('x',x);t.setAttribute('y',138);t.setAttribute('text-anchor','middle');t.textContent=fmt(n);g.append(line,t);el(id).append(g)}}ticks('#ticks');ticks('#move-ticks');
function update(){const n=Number(el('#pos').value),x=300+n*45;el('#point').setAttribute('cx',x);el('#point-label').setAttribute('x',x);el('#point-label').textContent='A = '+fmt(n);el('#distance-line').setAttribute('x2',x);el('#pos-value').value=fmt(n);el('#pos').setAttribute('aria-valuetext',fmt(n));el('#pos-feedback').textContent=n===0?'A berada tepat di nol. Jaraknya dari nol adalah 0 satuan. Nol bukan bilangan positif maupun negatif.':`A berada ${fmt(Math.abs(n))} satuan di ${n<0?'kiri':'kanan'} nol. Bilangannya ${n<0?'negatif':'positif'}, sedangkan jaraknya ${fmt(Math.abs(n))} satuan. |${fmt(n)}| = ${fmt(Math.abs(n))}.`;}
el('#pos').addEventListener('input',update);el('#ulang').addEventListener('click',()=>{el('#pos').value=-3;update()});update();
function movement(negative){const end=negative?525:255;el('#move-line').setAttribute('x2',end);el('#move-point').setAttribute('cx',end);el('#move-head').setAttribute('d',negative?`M${end} 55l-12-7v14Z`:`M${end} 55l12-7v14Z`);el('#move-feedback').textContent=negative?'2 − (−3) = 2 + 3 = 5. Mulai di 2, bergerak tiga satuan ke kanan, lalu tiba di 5. Mengurangi −3 sama dengan menambahkan lawannya, yaitu 3.':'2 − 3 = −1. Mulai di 2, bergerak tiga satuan ke kiri, lalu tiba di −1. Tanda minus di antara 2 dan 3 adalah operasi pengurangan.';document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.mode==='negative')===negative)))}document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>movement(b.dataset.mode==='negative')));movement(false);
el('#cek-awal').addEventListener('click',()=>{const selected=document.querySelector('input[name=awal]:checked');el('#awal-feedback').textContent=!selected?'Pilih satu dugaan dahulu. Tidak apa-apa jika belum yakin.':selected.value==='b'?'Tepat. −2 berada di kanan −5. Saat membaca, perhatikan perbedaan posisi dengan jarak dari nol.':selected.value==='a'?'Angka 5 memang lebih besar daripada 2, tetapi tanda negatif mengubah posisi bilangannya. Baca bagian posisi dan urutan, lalu bandingkan −5 dengan −2 di garis bilangan.':'Dua bilangan negatif dapat berbeda nilainya. Baca bagian posisi dan urutan untuk melihat letak −5 dan −2.'});
const qs=[{text:'Mana yang lebih besar: −4 atau −1? Tulis bilangannya.',answer:-1,hint:'Bilangan yang lebih besar terletak lebih ke kanan.',why:'−1 berada di kanan −4. Jadi −1 lebih besar.'},{text:'Berapa jarak titik −5,5 dari nol? Tulis dalam satuan.',answer:5.5,hint:'Jarak tidak bernilai negatif. Koma boleh dipakai untuk menulis desimal.',why:'Jaraknya 5,5 satuan, sehingga |−5,5| = 5,5.'},{text:'Mulai di −2, lalu bergerak 4 satuan ke kanan. Di bilangan berapa kamu tiba?',answer:2,hint:'Hitung empat langkah: −1, 0, 1, …',why:'Kamu tiba di 2. Gerakan ke kanan menambah nilai: −2 + 4 = 2.'},{text:'Hitung 1 − (−4).',answer:5,hint:'Bilangan yang dikurangi adalah −4. Apa lawannya?',why:'Lawan dari −4 adalah 4. Maka 1 − (−4) = 1 + 4 = 5.'}];const solved=new Set();el('#number-questions').innerHTML=qs.map((q,i)=>`<div class="question"><h3>Latihan ${i+1}</h3><p>${q.text}</p><form class="number-form" data-q="${i}"><label for="nanswer${i}">Jawaban latihan ${i+1}</label><div class="answer-line"><input id="nanswer${i}" type="text" inputmode="text" autocomplete="off" required aria-describedby="nfeedback${i}"><button class="button">Periksa jawaban</button></div></form><p id="nfeedback${i}" class="feedback" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-q]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const i=Number(f.dataset.q),raw=el('#nanswer'+i).value.trim().replace(/−/g,'-').replace(',','.');const valid=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw),correct=valid&&Number(raw)===qs[i].answer;const feedback=el('#nfeedback'+i);feedback.className='feedback '+(correct?'correct':'incorrect');feedback.textContent=correct?'Tepat. '+qs[i].why:!valid?'Tulis satu bilangan. Gunakan tanda minus untuk bilangan negatif, misalnya -2.':'Belum tepat. Bayangkan posisi dan arah pada garis bilangan, atau buka petunjuk.';if(correct)solved.add(i);el('#kemajuan').textContent=`${solved.size} dari ${qs.length} latihan telah dijawab dengan tepat.`}));
el('#number-reflection').value=save.get('reflection')||'';el('#number-reflection').addEventListener('input',()=>{el('#reflection-note').textContent=save.set('reflection',el('#number-reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan. Salin tulisanmu jika ingin menyimpannya.'});function completed(){el('#number-complete').textContent='Bacaan sudah ditandai selesai ✓';el('#kemajuan').textContent='Bacaan ditandai selesai ✓'}if(save.get('complete')==='yes')completed();el('#number-complete').addEventListener('click',()=>{const ok=save.set('complete','yes');completed();el('#number-complete-note').textContent=ok?'Kemajuan tersimpan pada peramban ini. Kamu boleh kembali berlatih kapan saja.':'Bacaan selesai. Penyimpanan kemajuan pada peramban ini belum tersedia.'});
